"""Refresh/check mobile export constants from the checked Python contract fixture."""

import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
TARGET = ROOT / "mobile/shared/src/commonMain/kotlin/org/cambridgeaudio/core/AnkiContract.kt"


def render():
    data = (ROOT / "contracts/anki.json").read_text(encoding="utf-8")
    # JSON as an escaped Kotlin string; dollar signs must not start interpolation.
    literal = json.dumps(data, ensure_ascii=False).replace("$", "\\$")
    return (
        "// Generated by scripts/mobile_contracts.py; verify with Python contract tests.\n"
        "package org.cambridgeaudio.core\n"
        f"internal val ankiContract = obj({literal})\n"
    )


if __name__ == "__main__":
    import sys

    if "--check" in sys.argv:
        if TARGET.read_text(encoding="utf-8") != render():
            raise SystemExit("Mobile Anki constants differ; run scripts/mobile_contracts.py")
    else:
        TARGET.write_text(render(), encoding="utf-8")
